/* ============ Psych charts v3 (built by tools/typec/lifechart.py; self-test: python3 tools/typec/lifechart.py) ============
   One visual language on every brief: time runs down; periwinkle = low mood; apricot = high mood; teal = psychosis, deeper
   the longer it lasts; hatched teal = a delusion only; an outlined psychosis segment = psychosis with no mood episode;
   red = danger. Names are HTML text with class "mask", so study mode hides them for recall. */
:root{--mlo:#DCE3F9;--mlo-e:#8B9FE3;--mhi:#FADFC7;--mhi-e:#DB9C62;--psy1:#DCF0EC;--psy2:#A9D8CF;--psy3:#2F7D73;--psy-e:#5FAEA2;--dng:#D2574B;--chart-ink:#2B2F36}
figure.lcb,figure.lc,figure.lct{margin:18px 0;padding:15px 15px 13px;border-radius:18px;background:var(--raised);box-shadow:inset 0 0 0 1px var(--hair);max-width:480px}
figure .ttl{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 12px;font-weight:700;font-size:15px;line-height:1.3}
figure .ttl > span{display:flex;align-items:center}
figure .ttl small{font-weight:600;font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);white-space:nowrap}
figure .step{display:inline-grid;place-items:center;flex:none;width:21px;height:21px;margin-right:9px;border-radius:50%;background:var(--chart-ink);color:#fff;font-size:11.5px;font-weight:700}
.lc-key{display:flex;flex-wrap:wrap;gap:7px 14px;margin:12px 0 0;font-size:12px;line-height:1.3;color:var(--muted)}
.lc-key span{display:inline-flex;align-items:center;gap:6px}
.lc-key i{display:inline-block;flex:none;width:15px;height:10px;border-radius:3px}
.k-lo{background:var(--mlo);box-shadow:inset 0 0 0 1.5px var(--mlo-e)} .k-hi{background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)}
.k-ps,.k-only,.k-free{background:repeating-linear-gradient(135deg,var(--psy-e) 0 2px,var(--psy1) 2px 5px);box-shadow:inset 0 0 0 1.5px var(--psy-e)}
.k-only{background:repeating-linear-gradient(135deg,var(--psy-e) 0 1.5px,#fff 1.5px 4px)}
.k-free{box-shadow:0 0 0 1.5px var(--chart-ink)}
.lc-key .k-dng{width:10px;border-radius:50%;background:var(--dng)}
.lc-key .k-pin{width:auto;height:auto;padding:0 5px;border-radius:9px;background:var(--chart-ink);color:#fff;font-style:normal;font-size:10px;font-weight:700;line-height:16px}

.k-w{width:22px!important;background:linear-gradient(90deg,var(--mhi) 0 42%,transparent 42% 58%,var(--mhi) 58%)} .k-w{box-shadow:none}
.k-sub{width:8px!important;background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)}
figure .note{margin:10px 0 0;font-size:13.5px;line-height:1.42}

/* duration bands */
.lcb .grid{display:grid;grid-template-columns:62px 1fr 14px;column-gap:9px}
.lcb .tk{grid-column:1 / 2;align-self:center;text-align:right;font-size:12px;font-weight:700;color:var(--chart-ink);white-space:nowrap;line-height:1}
.lcb .gate{grid-column:2 / 4;align-self:center;height:0;border-top:1.5px solid var(--chart-ink);opacity:.45}
.lcb .gnote{grid-column:2 / 4;justify-self:end;align-self:center;margin-right:22px;padding:1px 7px;border-radius:9px;background:var(--raised);box-shadow:inset 0 0 0 1px var(--hair);font-style:normal;font-size:10.5px;font-weight:600;color:var(--muted);white-space:nowrap;position:relative;z-index:1}
.lcb .spine{grid-column:1 / 2;justify-self:end;position:relative;width:2px;margin-right:4px;background:var(--muted);opacity:.55}
.lcb .spine.brk::after{content:"";position:absolute;left:-4px;top:calc(50% - 4px);width:10px;height:8px;background:linear-gradient(160deg,transparent 42%,var(--muted) 42% 58%,transparent 58%) 0 0/10px 4px,var(--raised)}
.lcb .band{grid-column:2 / 3;position:relative;margin:6px 0;padding:11px 12px;border-radius:12px;background:var(--c);min-height:58px}
.lcb .band .nm{display:block;font-weight:700;font-size:14.5px;line-height:1.3}
.lcb .band .rl{display:block;font-size:13px;line-height:1.38;margin-top:2px}
.lcb .band.deep{color:#fff}
.lcb .band.open{background:linear-gradient(var(--c) 70%,color-mix(in srgb,var(--c) 30%,transparent));padding-bottom:24px}
.lcb .band.open::after{content:"and longer";position:absolute;left:12px;bottom:6px;font-size:10px;letter-spacing:.07em;text-transform:uppercase;opacity:.8}
.lcb .inset{display:flex;margin-top:9px;height:20px;border-radius:6px;overflow:hidden;box-shadow:0 0 0 1px rgba(255,255,255,.55)}
.lcb .inset span{display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;letter-spacing:.02em;white-space:nowrap;overflow:hidden}
.lcb .inset .soft{background:repeating-linear-gradient(135deg,rgba(255,255,255,.28) 0 3px,rgba(255,255,255,.1) 3px 7px);color:#fff}
.lcb .inset .act{background:#fff;color:var(--psy3)}
.lcb .icap{display:block;margin-top:4px;font-size:11.5px;line-height:1.3;opacity:.92}
.lcb .only{grid-column:3 / 4;margin:6px 0;border-radius:7px;background:repeating-linear-gradient(135deg,var(--psy-e) 0 2px,#fff 2px 6px);box-shadow:inset 0 0 0 1.5px var(--psy-e)}
.lcb .pin,.lc-key .pin,.cases .pin{display:inline-grid;place-items:center;min-width:24px;height:18px;padding:0 5px;border-radius:9px;background:var(--chart-ink);color:#fff;font-size:10px;font-weight:700;box-shadow:0 0 0 2.5px var(--raised);position:relative;z-index:2}
.lcb .pin.band{justify-self:end;margin:10px 10px}
.lcb .pin.only{justify-self:center}
.lcb .cases{list-style:none;margin:10px 0 0;padding:0;font-size:12.5px;line-height:1.4;color:var(--muted)}
.lcb .cases li{display:flex;gap:8px;align-items:baseline;margin:4px 0}
.lcb .cases .pin.inl{flex:none;box-shadow:none}

/* small multiples against mood */
.lc .lanes-h,.lcs{display:grid;grid-template-columns:20px repeat(var(--n),1fr);column-gap:10px}
.lc .lanes-h{margin:0 0 4px;font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);grid-template-columns:20px repeat(calc(var(--n) * 2),1fr)}
.lc .lanes-h span:nth-child(even){text-align:left} .lc .lanes-h span:nth-child(odd){text-align:right}
.lcs .pn{align-self:end;margin-bottom:6px;font-size:12.5px;line-height:1.25;font-weight:700}
.lcs .axis{position:relative;height:var(--ph)}
.lcs .axis::before{content:"";position:absolute;left:8px;top:0;bottom:8px;width:2px;border-radius:1px;background:var(--muted);opacity:.7}
.lcs .axis::after{content:"";position:absolute;left:4px;bottom:0;border-left:5px solid transparent;border-right:5px solid transparent;border-top:9px solid var(--muted);opacity:.7}
.lcs .axis span{position:absolute;left:-1px;top:4px;writing-mode:vertical-rl;transform:rotate(180deg);font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);background:var(--raised);padding:3px 0;white-space:nowrap}
.lcs .pp{position:relative;height:var(--ph);border-radius:10px;background:linear-gradient(90deg,transparent 0 56%,rgba(21,21,27,.035) 56% 100%)}
.lcs .gd{position:absolute;left:-4px;right:-4px;top:var(--t);border-top:1px dotted rgba(21,21,27,.28)}
.lcs .mb{position:absolute;left:4%;width:46%;top:var(--t);height:var(--h);border-radius:7px}
.lcs .mb.lo{background:var(--mlo);box-shadow:inset 0 0 0 1.5px var(--mlo-e)} .lcs .mb.hi{background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)}
.lcs .pb{position:absolute;left:64%;width:28%;top:var(--t);height:var(--h);background:repeating-linear-gradient(135deg,var(--psy-e) 0 3px,var(--psy1) 3px 8px);box-shadow:inset 1.5px 0 0 var(--psy-e),inset -1.5px 0 0 var(--psy-e)}
.lcs .pb:first-of-type{border-radius:6px 6px 0 0}
.lcs .pb.free{box-shadow:0 0 0 2px var(--chart-ink);z-index:1}
.lcs .fl{position:absolute;left:0;width:56%;top:var(--t);height:var(--h);display:flex;align-items:center;justify-content:center;text-align:center;font-style:normal;font-size:10.5px;font-weight:700;line-height:1.2;color:var(--chart-ink)}
.lcs .mt{margin-top:9px}
.lcs .mt i{display:block;height:7px;border-radius:4px;background:linear-gradient(90deg,var(--mlo-e) 0 var(--s),var(--recess) var(--s) 100%)}
.lcs .mt span{display:block;margin-top:4px;font-size:10.5px;font-weight:600;color:var(--muted);letter-spacing:.02em}
.lcs .dc{margin:6px 0 0;font-size:12px;line-height:1.35;color:var(--chart-ink)}

/* threshold ruler */
.lct .rul{position:relative;margin-left:4px}
.lct .ax{position:absolute;left:62px;top:14px;bottom:14px;width:2px;background:var(--muted);opacity:.5}
.lct .rt{position:absolute;left:0;width:54px;transform:translateY(-50%);text-align:right;font-size:10.5px;font-weight:700;color:var(--muted);white-space:nowrap}
.lct .rtick{position:absolute;left:58px;width:10px;height:0;border-top:1.5px solid var(--muted);opacity:.6}
.lct .rl-svg{position:absolute;left:0;top:0;pointer-events:none}
.lct .rl-svg path{fill:none;stroke:var(--muted);stroke-width:1.2;opacity:.8}
.lct .rd{position:absolute;left:57px;width:12px;height:12px;margin-top:-6px;border-radius:50%;box-shadow:0 0 0 2.5px var(--raised)}
.lct .rd.lo{background:var(--mlo-e)} .lct .rd.hi{background:var(--mhi-e)} .lct .rd.ps{background:var(--psy3)} .lct .rd.mix{background:linear-gradient(90deg,var(--mlo-e) 50%,var(--mhi-e) 50%)}
.lct .rdg{position:absolute;left:73px;width:8px;height:8px;margin-top:-4px;border-radius:50%;background:var(--dng)}
.lct .rc{position:absolute;left:100px;right:0;box-sizing:border-box;padding:6px 10px;border-radius:10px;display:flex;flex-direction:column;justify-content:center}
.lct .rc.lo{background:var(--mlo);box-shadow:inset 3px 0 0 var(--mlo-e)} .lct .rc.hi{background:var(--mhi);box-shadow:inset 3px 0 0 var(--mhi-e)}
.lct .rc.ps{background:var(--psy1);box-shadow:inset 3px 0 0 var(--psy3)} .lct .rc.mix{background:linear-gradient(90deg,var(--mlo) 0 50%,var(--mhi) 50%);box-shadow:inset 3px 0 0 var(--mlo-e)}
.lct .rc .nm{font-weight:700;font-size:13px;line-height:1.25}
.lct .rc .rl{font-size:11.5px;line-height:1.3;color:var(--chart-ink)}
@media (max-width:360px){.lcs .dc{font-size:11.5px}}
.lcs .mb.split.lo{left:4%;width:22%} .lcs .mb.split.hi{left:28%;width:22%}
.lcs .mb.mild{width:30%} .lcs .mb.split.mild{width:15%}
.lcs .mb.sub{width:24%} .lcs .mb.split.sub{width:12%} .lcs .mb.split.hi.sub{left:28%}
.lcs .mb.opt{background:transparent;box-shadow:none;border:1.5px dashed var(--mlo-e);box-sizing:border-box}
.lcs .pdg{position:absolute;left:calc(50% - 7px);top:calc(var(--t) - 5px);width:10px;height:10px;border-radius:50%;background:var(--dng);box-shadow:0 0 0 2.5px var(--raised);z-index:2}
.lcs .mt.none{height:0;margin:0}
.k-opt{background:transparent;border:1.5px dashed var(--mlo-e);box-sizing:border-box}
.k-mild{width:9px!important;background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)}
.lcb .pin{justify-self:center}
.lct .ax{bottom:auto}
.lcs .ph{align-self:end}
.lcs .ph .pn{display:block;margin-bottom:6px}
.lcs .lh{display:grid;grid-template-columns:56% 44%;font-size:9px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:4px}
.lcs .lh span:first-child{padding-left:4%} .lcs .lh span:last-child{padding-left:12%}
.lcs .pb.free{box-shadow:0 0 0 1.75px var(--chart-ink)}
.lcs .mt.chip span{display:inline-block;margin-top:0;padding:2px 7px;border-radius:9px;background:var(--recess);font-size:10.5px;line-height:1.3;color:var(--chart-ink)}
.lct .rc.mix{background:linear-gradient(135deg,var(--mlo) 0 45%,var(--mhi) 75%)}
.lcs .lh{font-size:10px;letter-spacing:0;text-transform:none;overflow:hidden;white-space:nowrap}
.lcs .lh span:last-child{padding-left:14%}

/* ============ Psych charts v4: horizontal rows (lifechart.py window_rows / mood_tracks) ============
   Time runs left to right on one shared schematic axis. One row per diagnosis: name and window on the left (desktop) or
   on top (phone), the bar and its requirements beside it. Same palette and meanings as v3. */
figure.lcw{margin:18px 0;padding:15px 15px 12px;border-radius:18px;background:var(--raised);box-shadow:inset 0 0 0 1px var(--hair)}
.lcw .wax{display:grid;grid-template-columns:1fr;margin:2px 0 2px}
.lcw .wsp{display:none}
.lcw .wt{position:relative;height:16px;font-size:10.5px;font-weight:700;color:var(--muted);letter-spacing:.02em}
.lcw .wt span{position:absolute;left:var(--x);transform:translateX(-50%);white-space:nowrap}
.lcw .wt span[style*="--x:0%"]{transform:none}
.lcw .wt em{position:absolute;right:0;font-style:normal;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase}
.lcw .wt em::after{content:" \2192"}
.lcw .wrows{list-style:none;margin:0;padding:0}
.lcw .wr,.lcw .tr{padding:12px 0 11px;border-top:1px solid var(--hair)}
.lcw .wg{padding:14px 0 2px;font-size:10.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);border-top:1px solid var(--hair)}
.lcw .wg + .wr{border-top:0;padding-top:6px}
.lcw .wh{display:flex;flex-direction:column;gap:2px}
.lcw .wh .nm{font-weight:700;font-size:14.5px;line-height:1.3;color:var(--chart-ink)}
.lcw .wh .win{font-weight:700;font-size:13px;line-height:1.3;color:var(--psy3)}
.lcw .rail{position:relative;height:14px;margin:9px 0 8px;border-radius:7px;background:var(--recess)}
.lcw .rail .tk{position:absolute;left:var(--x);top:-3px;bottom:-3px;width:1.5px;margin-left:-.75px;background:var(--chart-ink);opacity:.22}
.lcw .rail .tk[style*="--x:0%"]{display:none}
.lcw .rail.segs .tk{opacity:.55;background:var(--chart-ink);z-index:1}
.lcw .bar{position:absolute;left:var(--a);width:calc(var(--b) - var(--a));top:0;bottom:0;border-radius:7px}
.lcw .bar.c1{background:var(--psy2)} .lcw .bar.c2{background:color-mix(in srgb,var(--psy2) 45%,var(--psy3))} .lcw .bar.c3{background:var(--psy3)}
.lcw .bar.only{background:repeating-linear-gradient(135deg,var(--psy-e) 0 2px,#fff 2px 6px);box-shadow:inset 0 0 0 1.5px var(--psy-e)}
.lcw .bar.exp{background:var(--psy2)}
.lcw .bar.open{border-radius:7px 0 0 7px;-webkit-mask:linear-gradient(90deg,#000 80%,transparent);mask:linear-gradient(90deg,#000 80%,transparent)}
.lcw .rail.segs{height:22px;margin-top:-2px;background:transparent}
.lcw .sg{position:absolute;left:var(--a);width:calc(var(--b) - var(--a));top:0;bottom:0;display:flex;align-items:center;justify-content:flex-start;padding-left:7px;box-sizing:border-box;font-size:10.5px;font-weight:700;white-space:nowrap;overflow:hidden}
.lcw .sg.soft{background:repeating-linear-gradient(135deg,var(--psy2) 0 3px,var(--psy1) 3px 7px);color:var(--psy3)}
.lcw .sg.act{background:var(--psy3);color:#fff}
.lcw .sg:first-of-type{border-radius:6px 0 0 6px} .lcw .sg:last-child{border-radius:0 6px 6px 0}
.lcw .segcap{margin:-4px 0 6px;font-size:12px;line-height:1.35;color:var(--muted)}
.lcw .wl{margin:3px 0 0;font-size:13.5px;line-height:1.42;color:var(--chart-ink)}
.lcw .wl b{margin-right:6px;font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
.lcw .cue{margin:4px 0 0;font-size:12.5px;line-height:1.38;color:var(--muted)}
.lcw .cue::before{content:"Cues ";font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase}
/* mood tracks */
.lcm .lanes{display:grid;grid-template-columns:64px 1fr;align-items:center;gap:5px 8px;margin:9px 0 2px}
.lcm .ln{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);text-align:right}
.lcm .lane{position:relative;height:16px;border-radius:5px;background:var(--recess)}
.lcm .mb,.lcm .pb{position:absolute;left:var(--a);width:calc(var(--b) - var(--a));top:0;bottom:0}
.lcm .mb{border-radius:5px} .lcm .mb.lo{background:var(--mlo);box-shadow:inset 0 0 0 1.5px var(--mlo-e)} .lcm .mb.hi{background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)}
.lcm .pb{background:repeating-linear-gradient(135deg,var(--psy-e) 0 3px,var(--psy1) 3px 8px);box-shadow:inset 0 1.5px 0 var(--psy-e),inset 0 -1.5px 0 var(--psy-e)}
.lcm .pb.free{box-shadow:0 0 0 2px var(--chart-ink);z-index:1;border-radius:2px}
.lcm .fls{position:relative;height:15px}
.lcm .fl{position:absolute;left:var(--a);width:calc(var(--b) - var(--a));text-align:center;font-style:normal;font-size:10.5px;font-weight:700;color:var(--chart-ink);white-space:nowrap}
@media (min-width:700px){
  .lcw .wax{grid-template-columns:190px 1fr;column-gap:18px} .lcw .wsp{display:block}
  .lcw .wr,.lcw .tr{display:grid;grid-template-columns:190px 1fr;column-gap:18px}
  .lcw .wh{flex-direction:column;gap:3px}
  .lcw .rail:first-child,.lcm .lanes{margin-top:3px}
}
/* workup path: an ordered workup on a vertical line with dots (lifechart.py workup_path) */
figure.lcp{margin:18px 0;padding:15px 15px 10px;border-radius:18px;background:var(--raised);box-shadow:inset 0 0 0 1px var(--hair)}
.lcp .path{list-style:none;margin:4px 0 0;padding:0}
.lcp .pt{position:relative;padding:0 0 18px 28px}
.lcp .pt::before{content:"";position:absolute;left:3px;top:3px;width:11px;height:11px;border-radius:50%;background:var(--chart-ink);box-shadow:0 0 0 3px var(--raised);z-index:1}
.lcp .pt::after{content:"";position:absolute;left:8px;top:8px;bottom:-4px;width:2px;background:var(--accent);opacity:.55}
.lcp .pt.end{padding-bottom:4px} .lcp .pt.end::after{content:none}
.lcp .when{display:block;margin:0 0 7px;font-size:10.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);line-height:1.4}
.lcp .pt:first-child .when{color:var(--accent)}
.lcp .tile{border-radius:14px;padding:11px 14px 12px;background:var(--raised);box-shadow:var(--e2),inset 0 0 0 1px var(--hair)}
.lcp .tile.first{background:linear-gradient(145deg,#F2F1FA 0%,#EDECF7 60%,#E9E8F4 100%);box-shadow:var(--e2),inset 0 0 0 1.5px rgba(84,74,196,.32)}
.lcp .plus{display:block;position:relative;height:0;margin:16px -14px 14px;border-top:1.5px dashed rgba(84,74,196,.35)}
.lcp .plus::after{content:"+";position:absolute;top:-13px;left:50%;transform:translateX(-50%);width:24px;height:24px;border-radius:50%;background:#F7F6FD;color:var(--accent);font:800 16px/24px var(--sans);text-align:center;box-shadow:0 0 0 1.5px rgba(84,74,196,.35)}
.lcp .tn{margin:0 0 4px;font-family:var(--serif);font-size:16.5px;font-weight:600;line-height:1.3;color:var(--ink)}
.lcp .wr2{display:grid;grid-template-columns:78px 1fr;gap:8px;margin:3px 0 0;font-size:14.5px;line-height:1.42}
.lcp .wr2 b{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);padding-top:3px}
.lcp .pt-tx{margin:0;font-size:14.5px;line-height:1.45}
/* bottom line: short paragraphs with indented lists */
.dp ul.bl{list-style:none;margin:-3px 0 11px 3px;padding:1px 0 1px 13px;border-left:2px solid rgba(84,74,196,.28)}
.dp ul.bl li{margin:0 0 3px;font-size:15.2px;line-height:1.45}
.dp ul.bl li:last-child{margin-bottom:0}
/* v4 mood bars and dashed "optional" pieces (bipolar), NBME question blocks */
.lcw .bar.hi{background:var(--mhi);box-shadow:inset 0 0 0 1.5px var(--mhi-e)} .lcw .bar.lo{background:var(--mlo);box-shadow:inset 0 0 0 1.5px var(--mlo-e)}
.lcw .bar.hi.mild{background:color-mix(in srgb,var(--mhi) 55%,#fff)}
.lcw .bar.mix{background:repeating-linear-gradient(90deg,var(--mhi) 0 10px,var(--mlo) 10px 20px);box-shadow:inset 0 0 0 1.5px var(--mlo-e)}
.lcw .sg.opt{z-index:2;background:var(--raised);color:var(--chart-ink);border:1.5px dashed var(--mhi-e);box-sizing:border-box;font-weight:600}
.lcm .mb.mild{background:color-mix(in srgb,var(--mhi) 55%,#fff)}
.lcm .mb.opt{background:transparent!important;box-shadow:none;border:1.5px dashed var(--mlo-e);box-sizing:border-box}
